/* app/globals.css */
@tailwind base;
@tailwind components;
@tailwind utilities;

body {
  background-color: #f7f7fb;
  color: #1b1b2f;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

export function Navbar() {
  return (
    <nav className="flex items-center justify-between px-12 py-5 bg-white border-b border-gray-100">
      <span className="text-2xl font-bold text-brandPurple">Lumen</span>
      <div className="flex items-center gap-8 text-sm font-medium text-textMain">
        <a href="#product" className="hover:text-brandPurple">Product</a>
        <a href="#pricing" className="hover:text-brandPurple">Pricing</a>
        <a href="#docs" className="hover:text-brandPurple">Docs</a>
        <a href="#blog" className="hover:text-brandPurple">Blog</a>
      </div>
      <button className="px-5 py-2 text-sm font-medium text-brandPurple border border-brandPurple rounded-md hover:bg-brandPurple/5">
        Sign in
      </button>
    </nav>
  );
}

export function FeatureCard({ title, description }: { title: string; description: string }) {
  return (
    <div className="p-8 bg-white rounded-xl border border-gray-100 shadow-sm flex flex-col justify-start">
      <h3 className="text-lg font-bold text-textMain mb-2">{title}</h3>
      <p className="text-sm text-textMuted leading-relaxed">{description}</p>
    </div>
  );
}

import { NextResponse } from 'next/server';
export async function POST(req: Request) {
  const { email, name } = await req.json();
  if (!email || !email.includes('@')) {
    return NextResponse.json({ error: 'Valid email required' }, { status: 400 });
  }
  // Supabase insert lead
  return NextResponse.json({ success: true, message: 'Demo booked' });
}

export function DemoModal({ isOpen, onClose }: { isOpen: boolean; onClose: () => void }) {
  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 bg-black/40 flex items-center justify-center p-4 z-50">
      <div className="bg-white p-6 rounded-lg max-w-sm w-full relative">
        <h3 className="font-bold text-lg mb-2">Book a Demo</h3>
        <input placeholder="Work email" className="w-full border p-2 rounded mb-4 text-sm" />
        <button onClick={onClose} className="w-full bg-brandPurple text-white py-2 rounded text-sm">Submit</button>
      </div>
    </div>
  );
}

/* Ensure accessibility focus rings */
button:focus-visible, a:focus-visible {
  outline: 2px solid #4b3fe0;
  outline-offset: 2px;
}
